@dataclass(frozen=True)
class Focus:
    tag: str
    slug: str
    x: int
    y: int
    cost: int
    prerequisites: tuple
    exclusive: tuple
    gates: tuple
    ai: int
    reward: tuple
    subjects: tuple
    title: str
    desc: str
    order: int

    @property
    def id(self):
        return "%s_ud_%s" % (self.tag, self.slug)


def _parse():
    rows = []
    for tag, raw in DATA.items():
        for line in raw.strip().splitlines():
            parts = [p.strip() for p in line.split("|")]
            if len(parts) != 11:
                raise ValueError("Malformed focus row: " + line[:60])
            slug, at, cost, pre, mutex, gate, ai, reward, subjects, title, desc = parts
            x, y = map(int, at.split())
            prerequisites = tuple(tuple(tag + "_ud_" + s for s in block.split("/")) for block in pre.split()) if pre != "-" else ()
            exclusive = tuple(tag + "_ud_" + s for s in mutex.split()) if mutex != "-" else ()
            rows.append(Focus(tag, slug, x, y, int(cost), prerequisites, exclusive, tuple(gate.split()) if gate != "-" else (),
                              int(ai), tuple(reward.split(";")) if reward != "-" else (), tuple(subjects.split()), title, desc, len(rows)))
    return rows


FOCUSES = _parse()
BY_ID = {row.id: row for row in FOCUSES}
if len(BY_ID) != len(FOCUSES):
    raise ValueError("Duplicate Usea Depth partner focus IDs")
